import json

import numpy as np


def open_text(path):
    with open(path, "rb") as fh:
        magic = fh.read(2)
    if magic == b"\x1f\x8b":
        return gzip.open(path, "rt")
    return open(path, "rt")


def read_mtx(path):
    with open_text(path) as fh:
        header = fh.readline().strip().split()
        if len(header) < 5 or header[0] != "%%MatrixMarket":
            raise RuntimeError("not a MatrixMarket file")
        obj, fmt, field, symmetry = header[1:5]
        line = fh.readline()
        while line.startswith("%"):
            line = fh.readline()
        dims = [int(x) for x in line.split()]
        if fmt == "array":
            nrow, ncol = dims[:2]
            vals = np.fromiter(
                (float(x.strip()) for x in fh if x.strip()),
                dtype=float,
                count=nrow * ncol,
            )
            if vals.size != nrow * ncol:
                raise RuntimeError("array value count mismatch")

        if not isinstance(output, Mapping):
            continue
        compact.append(
            {
                "format": output.get("format") or output.get("format_source"),
                "label": output.get("label"),
                "name": output.get("name"),
            }
        )
    return compact


def _filter_fields(
    fields: Sequence[Mapping[str, Any]],
    terms: Sequence[str],
) -> list[Mapping[str, Any]]:
    normalized = [term.lower() for term in terms if term.strip()]
    if not normalized:
        return list(fields)
    return [
        field
        for field in fields
        if any(term in json.dumps(field, sort_keys=True).lower() for term in normalized)
    ]


